import {normalize,LIMITS} from './engine.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',chart:'<path d="M4 3v17h17M8 15V9m5 6V5m5 10v-4"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V5Z"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',flask:'<path d="M9 3h6m-5 0v7L5 19a1 1 0 0 0 1 2h12a1 1 0 0 0 1-2l-5-9V3M8 14h8"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M5 7v8a4 4 0 0 0 4 4h8M7 5h8a4 4 0 0 1 4 4v3m-3-3 3 3 3-3"/>'};
$$('[data-icon]').forEach(e=>{e.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[e.dataset.icon]||paths.book)+'</svg>'});
let worker,documents=[],demoDocuments=[],dictionary={},license={},result=null,batch=null,budget=1,busy=false,ready=false,pendingCorpus=null,exportId=0,toastTimer;
const exports=new Map(),labels={studio:'Phòng thử nghiệm',dataset:'Tạo dataset',research:'Kết quả nghiên cứu',method:'Phương pháp'};
const fmt=n=>Number(n).toLocaleString('vi-VN'),el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500)}
function route(page,write=true){if(!labels[page])page='studio';$$('[data-view]').forEach(e=>e.hidden=e.dataset.view!==page);$$('[data-page]').forEach(e=>{e.classList.toggle('active',e.dataset.page===page);e.setAttribute('aria-current',e.dataset.page===page?'page':'false')});$('#page-label').textContent=labels[page];$('.sidebar').classList.remove('open');if(write)location.hash=page;window.scrollTo(0,0);updateBatchSettings()}
$$('[data-page]').forEach(e=>e.addEventListener('click',()=>route(e.dataset.page)));$$('[data-route]').forEach(e=>e.addEventListener('click',e2=>{e2.preventDefault();route(e.dataset.route)}));window.addEventListener('hashchange',()=>route(location.hash.slice(1),false));$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');route(location.hash.slice(1),false);
function options(){return {budget,channel:$('#channel').value,contextCap:Number($('#context-cap').value)}}
function tokenCount(){$('#token-count').textContent=normalize($('#query').value).split(' ').filter(Boolean).length+' / 16 token'}
function setBusy(state){busy=state;$('#result-panel').classList.toggle('busy',state);$('#cancel').hidden=!state;$('#cancel-batch').hidden=!state;for(const s of ['#run-query','#run-batch','#query','#channel','#context-cap','#corpus-file','#reset-corpus','#batch-queries','#run-witness'])$(s).disabled=state||(!ready&&['#run-query','#run-batch'].includes(s));$$('[data-budget],[data-example]').forEach(e=>e.disabled=state);$('#export-proof').disabled=state||!result;$('#export-dataset').disabled=state||!batch}
function invalidate(){result=null;$('#export-proof').disabled=true;$('#depth-value').textContent='—';$('#result-status').className='badge neutral';$('#result-status').textContent='Cần chạy lại';$('#depth-description').textContent='Chạy với truy vấn và cấu hình hiện tại để xem cận chứng nhận.';for(const s of ['pair','graph','exact']){$('#'+s+'-value').textContent='—';$('#'+s+'-bar').style.width='0%'}$('#state-count').textContent='—';$('#time-value').textContent='—';$('#ranking-list').replaceChildren();$('#ranking-empty').hidden=false;$('#witness-content').hidden=true;$('#witness-empty').hidden=false;$('#groups-details').hidden=true;batch=null;$('#export-dataset').disabled=true;$('#batch-summary').textContent='';$('#batch-progress').textContent='';updateBatchSettings()}
function updateBatchSettings(){const e=$('#batch-settings');if(e)e.textContent=(documents.length?fmt(documents.length)+' tài liệu · ':'')+$('#channel').selectedOptions[0].textContent+' · tối đa '+budget+' token bị sửa · cap '+$('#context-cap').value}
function makeWorker(){if(worker)worker.terminate();worker=new Worker('./worker.mjs',{type:'module'});worker.onmessage=handle;worker.onerror=e=>{setBusy(false);toast('Worker không chạy được: '+e.message)}}
function loadCorpus(docs,name,kind){if(!Array.isArray(docs)||!docs.length)throw Error('Không có tài liệu.');if(docs.length>LIMITS.documents)throw Error('Tối đa 500 tài liệu.');if(docs.reduce((s,d)=>s+String(d.text||'').length+String(d.title||'').length,0)>LIMITS.characters)throw Error('Corpus vượt 500.000 ký tự.');pendingCorpus={docs,name,kind};ready=false;setBusy(true);$('#corpus-description').textContent='Đang dựng chỉ mục…';worker.postMessage({type:'init',documents:docs,dictionary})}
function renderDocs(){const filter=normalize($('#filter-corpus').value),container=$('#corpus-docs');container.replaceChildren();for(const d of documents.filter(d=>normalize(d.id+' '+d.title).includes(filter)).slice(0,50)){const e=el('div','corpus-doc');e.append(el('b','',d.title||d.id),el('p','',d.id+' · '+d.text.slice(0,150)));container.append(e)}}
async function handle({data:m}){
 if(m.type==='ready'){if(pendingCorpus){documents=pendingCorpus.docs;$('#corpus-name').textContent=pendingCorpus.name;$('#corpus-kind').textContent=pendingCorpus.kind;pendingCorpus=null}ready=true;setBusy(false);invalidate();$('#result-status').textContent='Sẵn sàng';$('#corpus-description').textContent=fmt(m.documents)+' tài liệu · '+fmt(m.features)+' n-gram · index cục bộ';renderDocs()}
 if(m.type==='result'){result=m.result;setBusy(false);showResult(result)}
 if(m.type==='progress')$('#batch-progress').textContent='Đã xử lý '+m.done+' / '+m.total+' truy vấn…';
 if(m.type==='batch'){batch=m.results;setBusy(false);$('#batch-progress').textContent='Hoàn tất '+batch.length+' / '+batch.length+' truy vấn.';const exact=batch.filter(r=>r.lattice.enumerationStatus==='exact').length;$('#batch-summary').textContent=exact+' bản ghi có oracle chính xác; '+(batch.length-exact)+' bản ghi giữ trạng thái oracle chưa biết. Tệp xuất kèm corpus và trọng số để kiểm tra lại.'}
 if(m.type==='error'){pendingCorpus=null;setBusy(false);toast(m.message);$('#batch-progress').textContent=busy?'':'Nếu đang tạo batch, chưa xuất batch chưa hoàn tất.'}
 if(m.type==='bundle'){const job=exports.get(m.requestId??m.kind);if(!job)return;exports.delete(m.requestId??m.kind);const sample=Array.isArray(job.payload)?job.payload[0]:job.payload;if(sample.modelHash!==m.modelHash||sample.corpusHash!==m.corpusHash){toast('Corpus đã đổi; hãy chạy lại trước khi xuất.');return}const manifest={schema:'ngramlab.bundle.v1',recordType:'manifest',kind:job.kind,createdAt:new Date().toISOString(),corpus:m.corpus,weights:m.weights,corpusHash:m.corpusHash,modelHash:m.modelHash,provenance:{corpus:{origin:job.corpusOrigin,license:job.corpusOrigin==='authored-synthetic'?'CC0-1.0':'unspecified by uploader; no redistribution rights granted by this tool'},dictionary:Object.fromEntries(Object.entries(license).filter(([k])=>!['synthetic_corpus_license','combined_audit_dataset_license'].includes(k)))},scope:'Finite-token-edit retention of original reference; synthetic/curated transformations; no relevance or semantic labels. Local user content, review before sharing.',splitRule:'Browser export groups identical normalized query strings only; near-duplicate grouping is NOT automatic.'};if(job.kind==='proof'){download('ngram-certificate.json',JSON.stringify({manifest,result:job.payload},null,2),'application/json')}else{const lines=[JSON.stringify(manifest)];for(const r of job.payload){const group=await sha(normalize(r.query));lines.push(JSON.stringify({...r,recordType:'case',sourceQueryGroup:group,split:parseInt(group.slice(0,8),16)%5===0?'evaluation':'development'}))}download('ngram-audit.jsonl',lines.join('\n')+'\n','application/x-ndjson')}toast('Đã tạo tệp trên máy bạn. Kiểm tra nội dung trước khi chia sẻ.')}
}
function showResult(r){const names={certified:['Đã chứng nhận','good'],inconclusive:['Chưa kết luận','neutral'],witness_exceeds_cap:['Witness vượt cap','warning']},[label,style]=(r.budget>0&&r.lattice.states===1&&r.policy.status==='certified'?['Chỉ bản gốc','neutral']:names[r.policy.status]);$('#result-status').textContent=label;$('#result-status').className='badge '+style;$('#depth-value').textContent=r.bounds.proposed;$('#depth-description').textContent=r.policy.status==='certified'?'Cận đủ không vượt cap '+r.policy.cap+'. '+(r.policy.depthIsExactMinimum?'Oracle đã liệt kê đủ lattice.':'Đây là độ sâu bảo thủ, chưa khẳng định nhỏ nhất.'):'Cận hiện tại lớn hơn cap '+r.policy.cap+'. '+(r.policy.status==='witness_exceeds_cap'?'Witness đã đạt rank vượt cap.':'Chưa có witness vượt cap: giữ trạng thái chưa kết luận.');
 if(r.budget>0&&r.lattice.states===1)$('#depth-description').textContent+=' Bộ lỗi hiện tại không tạo biến thể ngoài bản gốc; chưa đánh giá lỗi khác.';const max=Math.max(r.bounds.pairwise,1);for(const [key,value] of [['pair',r.bounds.pairwise],['graph',r.bounds.discrete],['exact',r.bounds.exact]]){$('#'+key+'-value').textContent=value===null?'Chưa liệt kê đủ':fmt(value);$('#'+key+'-bar').style.width=value===null?'0%':100*value/max+'%'}$('#state-count').textContent=fmt(r.lattice.states);$('#time-value').textContent=r.elapsedMs<1000?Math.round(r.elapsedMs)+' ms':(r.elapsedMs/1000).toFixed(2)+' s';$('#witness-empty').hidden=true;$('#witness-content').hidden=false;$('#witness-query').textContent=r.witness.text;$('#witness-description').textContent='Rank quan sát (hòa bất lợi): '+r.witness.rank+' · '+r.witness.operations.length+' token đổi. '+(r.witness.operations.length?'Phép sửa: '+r.witness.operations.map(x=>x.op).join(', '):'Không cần sửa token.');
 $('#ranking-empty').hidden=true;$('#ranking-caption').textContent='Truy vấn: '+r.query;const list=$('#ranking-list');list.replaceChildren();r.cleanRanking.slice(0,10).forEach((d,i)=>{const e=el('article','rank-row'+(d.id===r.referenceId?' ref':'')),body=el('div','rank-body'),id=el('div','rank-id',d.id);if(d.id===r.referenceId)id.append(el('span','badge good','Tham chiếu'));body.append(el('div','rank-title',d.title||d.id),el('div','rank-excerpt',d.text.slice(0,210)+(d.text.length>210?'…':'')),id);const score=el('div','rank-score',d.score.toFixed(3));score.append(el('small','','điểm'));e.append(el('div','rank-number',i+1),body,score);list.append(e)});
 $('#groups-details').hidden=false;const groups=$('#proof-groups');groups.replaceChildren();for(const group of r.proof.groups.slice(0,30)){const e=el('span','proof-group',group.join(' · '));e.title=group.join(', ');groups.append(e)}if(!r.proof.groups.length)groups.append(el('span','muted','Không có đối thủ có thể vượt trong lattice đã xét.'));$('#export-proof').disabled=false
}
$('#run-query').onclick=()=>{if(!ready||busy)return;result=null;setBusy(true);$('#result-status').textContent='Đang tính…';worker.postMessage({type:'query',query:$('#query').value,options:options()})};
$('#query').addEventListener('input',()=>{tokenCount();invalidate()});$('#query').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')$('#run-query').click()});
$$('[data-example]').forEach(e=>e.onclick=()=>{$('#query').value=e.dataset.example;tokenCount();invalidate();$('#query').focus()});
$$('[data-budget]').forEach(e=>e.onclick=()=>{budget=Number(e.dataset.budget);$$('[data-budget]').forEach(b=>b.classList.toggle('selected',b===e));invalidate()});
$('#channel').onchange=()=>{$('#channel-hint').textContent={keyboard:'Một phép xóa, đảo, lặp hoặc thay phím kề trên mỗi token.',curated:'Lựa chọn hữu hạn từ dictionary đã pin; không biểu diễn tần suất lỗi.',accents:'Bỏ dấu một token gốc; phép biến đổi không bảo đảm giữ nghĩa.',mixed:'Hợp các lựa chọn lỗi; mỗi token chọn một trạng thái.'}[$('#channel').value];invalidate()};
$('#context-cap').onchange=invalidate;$('#show-corpus').onclick=()=>{$('#corpus-preview').hidden=!$('#corpus-preview').hidden};$('#filter-corpus').oninput=renderDocs;
$('#reset-corpus').onclick=()=>{try{loadCorpus(demoDocuments,'Knowledge Base · EN / VI','Tổng hợp')}catch(e){toast(e.message)}};
$('#cancel').onclick=()=>{makeWorker();ready=false;setBusy(false);invalidate();toast('Đã dừng. Đang khôi phục chỉ mục; không kết luận từ phép chạy dở.');loadCorpus(documents,$('#corpus-name').textContent,$('#corpus-kind').textContent)};
$('#cancel-batch').onclick=()=>$('#cancel').click();
$('#run-witness').onclick=()=>{if(!result)return;$('#query').value=result.witness.text;tokenCount();invalidate();$('#run-query').click()};
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if(c==='\n'&&!quote){row.push(cell.replace(/\r$/,''));if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('CSV có dấu ngoặc kép chưa đóng.');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}const header=rows.shift()?.map(x=>x.trim().toLowerCase());if(!header||(!header.includes('text')&&!header.includes('title')))throw Error('CSV cần cột text hoặc title; id là tùy chọn.');return rows.map((r,i)=>Object.fromEntries(header.map((h,j)=>[h,r[j]||''])))}
$('#corpus-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000)throw Error('Tệp quá 2 MB.');const text=await file.text();let a;if(file.name.endsWith('.csv'))a=parseCSV(text);else if(file.name.endsWith('.jsonl'))a=text.split(/\r?\n/).filter(s=>s.trim()).map((s,i)=>{try{return JSON.parse(s)}catch{throw Error('JSONL không hợp lệ tại dòng '+(i+1))}});else{const x=JSON.parse(text);a=Array.isArray(x)?x:x.documents}if(!Array.isArray(a))throw Error('JSON cần mảng tài liệu hoặc trường documents.');const docs=a.map((d,i)=>({id:String(d.id||i+1),title:String(d.title||''),text:String(d.text||'')}));if(new Set(docs.map(d=>d.id)).size!==docs.length)throw Error('ID tài liệu trùng.');loadCorpus(docs,file.name,'Tệp của bạn');toast('Đọc tệp cục bộ. Nội dung không được tải lên máy chủ.')}catch(err){toast(err.message)}finally{e.target.value=''}};
$('#batch-queries').oninput=()=>{$('#batch-count').textContent=$('#batch-queries').value.split(/\r?\n/).filter(x=>x.trim()).length+' truy vấn';batch=null;$('#export-dataset').disabled=true};
$('#run-batch').onclick=()=>{const queries=$('#batch-queries').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(!queries.length||queries.length>30){toast('Nhập từ 1 đến 30 truy vấn.');return}if(!ready)return;batch=null;setBusy(true);$('#batch-progress').textContent='Bắt đầu 0 / '+queries.length+'…';$('#batch-summary').textContent='';worker.postMessage({type:'batch',queries,options:options()})};
function queueExport(kind,payload){if(!payload)return;const id=++exportId;exports.set(id,{kind,payload:structuredClone(payload),corpusOrigin:$('#corpus-kind').textContent==='Tổng hợp'?'authored-synthetic':'user-provided'});worker.postMessage({type:'bundle',kind,requestId:id})}
$('#export-proof').onclick=()=>queueExport('proof',result);$('#export-dataset').onclick=()=>queueExport('dataset',batch);
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function sha(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
for(const [name,lp,discrete] of [['SciFact',57.79,61.81],['NFCorpus',18.39,20.18],['FiQA',12.96,16.61]]){const row=el('div','chart-row'),bars=el('div','chart-pair');for(const value of [lp,discrete]){const bar=el('i');bar.style.width=value+'%';bar.title=value+'%';bars.append(bar)}row.append(el('span','',name),bars,el('b','',discrete.toFixed(2)+'%'));$('#research-chart').append(row)}
try{const responses=await Promise.all(['data/demo-corpus.json','data/typos.json','data/data-license.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error('Không tải được '+p);return r.json()})));demoDocuments=responses[0].documents;dictionary=responses[1];license=responses[2];makeWorker();loadCorpus(demoDocuments,'Knowledge Base · EN / VI','Tổng hợp')}catch(e){toast(e.message+' · Hãy tải lại trang.')}
tokenCount();
